const { verifyMetaWebhook } = require('/home/node/scripts/cvpro-helpers.js');
const query = $input.first().json.query || {};
const result = verifyMetaWebhook(query, process.env.INSTAGRAM_VERIFY_TOKEN);
return [{ json: result }];

const body = $input.first().json.body;
const entry = body?.entry?.[0];
const messaging = entry?.messaging?.[0];
if (messaging?.message?.text) {
  return [{ json: { type: 'dm', from: messaging.sender.id, text: messaging.message.text, pageId: entry.id, timestamp: messaging.timestamp } }];
}
const changes = entry?.changes?.[0];
if (changes?.field === 'comments' && changes?.value?.message) {
  return [{ json: { type: 'comment', from: changes.value.from.id, fromName: changes.value.from.name, text: changes.value.message, commentId: changes.value.id, mediaId: changes.value.media?.id, pageId: entry.id } }];
}
return [];

const {
  getOrCreateCustomer,
  getOrCreateConversation,
  getMessageHistory,
  formatHistory,
  saveMessage,
  updateCustomer,
} = require('/home/node/scripts/cvpro-helpers.js');
const { GeminiRotator } = require('/home/node/scripts/gemini-rotation.js');

const { text: userMsg, from: senderId, pageId } = $input.first().json;

const customer = await getOrCreateCustomer($http, { instagram_id: senderId });
const conversation = await getOrCreateConversation($http, customer.id, 'instagram');

if (conversation.human_takeover) {
  return [{ json: { skipReply: true, from: senderId, pageId } }];
}

await saveMessage($http, conversation.id, 'inbound', userMsg, { is_ai_generated: false });

const messages = await getMessageHistory($http, conversation.id, 10);
const history = formatHistory(messages);

const systemPrompt = `أنت وكيل مبيعات CVPro.ae على إنستاجرام. الأسعار: Essential 399 | LinkedIn 299 | Career Boost 599 | Executive 999 درهم. رد مختصر وودي.\n${history}`;
const rotator = new GeminiRotator(process.env.GEMINI_API_KEYS.split(','));
let aiReply = '';
try {
  aiReply = await rotator.call(userMsg, systemPrompt, 300, 0.7);
} catch (_) {
  aiReply = 'مرحباً! كيف أساعدك اليوم؟ 😊';
}

await saveMessage($http, conversation.id, 'outbound', aiReply, { is_ai_generated: true, ai_model: 'gemini-2.5-flash' });
await updateCustomer($http, customer.id, { last_interaction: new Date().toISOString() });

return [{ json: { reply: aiReply, from: senderId, pageId } }];

const { GeminiRotator } = require('/home/node/scripts/gemini-rotation.js');
const commentText = $input.first().json.text;
const commentId = $input.first().json.commentId;
const prompt = `أنت مساعد CVPro.ae. رد على تعليق: "${commentText}" برد قصير (جملتين) وادعُ للـ DM. لا تذكر الأسعار.`;
const rotator = new GeminiRotator(process.env.GEMINI_API_KEYS.split(','));
let reply = '';
try {
  reply = await rotator.call(prompt, '', 80, 0.5);
} catch (_) {
  reply = 'شكراً لتعليقك! 😊 راسلنا على الـ DM للمزيد.';
}
await $http.request({
  method: 'POST',
  url: `https://graph.facebook.com/v21.0/${commentId}/replies`,
  headers: { Authorization: `Bearer ${process.env.INSTAGRAM_ACCESS_TOKEN}`, 'Content-Type': 'application/json' },
  body: { message: reply },
});
return [{ json: { success: true, commentId, reply } }];
